CREATE TYPE "user_role" AS ENUM (
  'member',
  'moderator',
  'admin'
);

CREATE TYPE "post_status" AS ENUM (
  'draft',
  'published',
  'archived'
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY UNIQUE NOT NULL,
  "username" varchar(80) UNIQUE NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "display_name" varchar(120),
  "role" user_role NOT NULL DEFAULT 'member',
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "referrer_id" integer
);

CREATE TABLE "posts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "author_id" integer NOT NULL,
  "title" varchar(200) NOT NULL,
  "slug" varchar(220) UNIQUE NOT NULL,
  "body" text,
  "status" post_status NOT NULL DEFAULT 'draft',
  "published_at" timestamp
);

CREATE TABLE "comments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "post_id" integer NOT NULL,
  "author_id" integer NOT NULL,
  "body" text NOT NULL
);

CREATE TABLE "sessions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "token" varchar(128) UNIQUE NOT NULL,
  "expires_at" timestamp NOT NULL
);

CREATE TABLE "audit_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "event" varchar,
  "masked_id" integer
);

CREATE TABLE "likes" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "post_id" integer NOT NULL
);

CREATE INDEX "idx_sessions_user" ON "sessions" ("user_id");

CREATE INDEX "idx_sessions_user_expiry" ON "sessions" USING HASH ("user_id", "expires_at");

COMMENT ON COLUMN "users"."id" IS 'The user identifier — hover the paper icon to read me';

COMMENT ON COLUMN "users"."username" IS 'Login handle, unique across the instance';

COMMENT ON COLUMN "users"."referrer_id" IS 'Self-reference: who invited this user';

COMMENT ON COLUMN "posts"."author_id" IS 'FK side of the link icon';

COMMENT ON COLUMN "posts"."body" IS 'Markdown body — can be very long, notes are capped at 60 chars in the tooltip';

COMMENT ON COLUMN "comments"."post_id" IS 'Which post this comment belongs to';

ALTER TABLE "likes" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "likes" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts" ADD FOREIGN KEY ("author_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "comments" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "comments" ADD FOREIGN KEY ("author_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users" ADD FOREIGN KEY ("referrer_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "sessions" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
